	"com/erpis/shiperp/createshipmentewm/fragment/packing/AddProductDetail.fragment.xml":'<core:FragmentDefinition xmlns:core="sap.ui.core" xmlns="sap.m" xmlns:l="sap.ui.layout" xmlns:f="sap.ui.layout.form"><Dialog title="Add product Details" class="sapUiContentPadding" contentWidth="800px"><content><VBox class="sapUiSmallMargin"><f:SimpleForm editable="true" layout="ResponsiveGridLayout" labelSpanXL="4" labelSpanL="3" labelSpanM="4" labelSpanS="4"\n\t\t\t\t\tadjustLabelSpan="false" emptySpanXL="0" emptySpanL="4" emptySpanM="0" emptySpanS="0" columnsXL="2" columnsL="1" columnsM="1"\n\t\t\t\t\tsingleContainerFullSize="false"><f:content><Label text="Product"/><Input value="{local>/NewHazMatItem/Actualqty}"/><Label text="Description"/><Input value="{local>/NewHazMatItem/Packweight}"/><Label text="Quantity/ UoM/ Weight/ UoM"/><Input value="{local>/NewHazMatIeight}"/><Input value="{local>/NewHazMatIt}"/><Input value="{local>/NewHazMatItem}"/><Input value="{local>/NewHazMatItem/Dgregulation}"/><Label text="NeValue/ Unit Price/ Currency"/><Input value="{local>/NewHazMatItershipnam}"/><Input value="{local>/NewHazMatIem}"/><Input value="{local>/Newpnam}"/><Label text="Harmonized Code/ COO"/><Input value="{local>/NewHazMatItess}"/><Input value="{local>/NewHass}"/></f:content></f:SimpleForm></VBox></content><beginButton><Button text="Ok" type="Emphasized" press="onProductionDetailPress"/></beginButton><endButton><Button press="onProductDetailsClose" text="{i18n>Cancel}"/></endButton></Dialog></core:FragmentDefinition>',
	"com/erpis/shiperp/createshipmentewm/fragment/packing/AdvancedPackingDialog.fragment.xml":'<core:FragmentDefinition xmlns:core="sap.ui.core" xmlns="sap.m" xmlns:l="sap.ui.layout" xmlns:form="sap.ui.layout.form" xmlns:fiori="sap.f"><Dialog id="dialogAdvancedPacking" title="{i18n>advancedPackingByMaterial}" stretch="true" beforeClose="onAdvancedPackingDialogBeforeClose"><content><Carousel id="AdvancePackingCarousel" class="sapUiContentPadding" height="100%" width="100%" arrowsPlacement="PageIndicator"\n\t\t\t\tpageChanged="onAdvancedPackingPageChanged"><core:Fragment id="advancedModeMaterial" class="sapUiSizeCompact" fragmentName="com.erpis.shiperp.createshipmentewm.fragment.packing.ItemsPacking"\n\t\t\t\t\ttype="XML"/><core:Fragment id="advancedModeHU" class="sapUiSizeCompact" fragmentName="com.erpis.shiperp.createshipmentewm.fragment.packing.HUPacking" type="XML"/></Carousel></content><endButton><Button text="{i18n>Close}" press="onCloseAdvancedPackingDialog"/></endButton></Dialog></core:FragmentDefinition>',
